import React from 'react';

/**
 * DownloadResults Component
 *
 * Displays the available download options for a fetched video URL.
 * Includes default props to act as a "blueprint" for previewing.
 *
 * @param {object} props - Component props.
 * @param {Array<object>} [props.options] - Array of download option objects. Each object should have `quality`, `url`, `format`, and optionally `size`. Defaults to placeholder data.
 * @param {string} [props.url] - The original video URL for which the options were fetched. Defaults to a placeholder URL.
 * @param {function} [props.onDownloadAnother] - Callback function to trigger going back to the input form. Defaults to a console log message.
 */
const DownloadResults = ({
  // --- Default Props for Blueprint/Preview ---
  options = [
    { quality: 'HD', url: '#', format: 'MP4', size: 'Approx. 50MB' },
    { quality: 'SD', url: '#', format: 'MP4', size: 'Approx. 20MB' },
    { quality: 'Audio', url: '#', format: 'MP3', size: 'Approx. 5MB' },
  ],
  url = 'https://www.facebook.com/watch/?v=1234567890', // Placeholder URL
  onDownloadAnother = () => console.log('Download Another button clicked (placeholder)'), // Placeholder function
}) => {

  // --- Handling No Options ---
  // Check if options array is empty or not provided (after defaults applied)
  if (!options || options.length === 0) {
    return (
        <div className="w-full max-w-xl bg-white dark:bg-gray-900 rounded-lg shadow-md dark:shadow-lg p-6 md:p-8 mx-4 text-center">
            <p className="text-gray-600 dark:text-gray-400 mb-4">No download options available for this URL.</p>
             <button
                onClick={onDownloadAnother} // Use the provided or default function
                className="bg-blue-600 hover:bg-blue-700 dark:bg-blue-700 dark:hover:bg-blue-600 text-white font-bold py-2 px-4 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-opacity-50 transition-colors duration-300"
            >
                Try Another URL
            </button>
        </div>
    );
  }

  // --- Rendering Download Options ---
  return (
    // Container for the download results section
    <div className="w-full max-w-xl bg-white dark:bg-gray-900 rounded-lg shadow-md dark:shadow-lg p-6 md:p-8 mx-4">
      {/* Title for the results section */}
      <h2 className="text-2xl font-semibold text-gray-800 dark:text-gray-200 mb-4 text-center">
        Download Options
      </h2>
      {/* Display the original URL (or placeholder) */}
      <p className="text-sm text-gray-600 dark:text-gray-400 mb-5 text-center break-all">
        Video URL: <span className="font-mono bg-gray-100 dark:bg-gray-700 px-1 rounded">{url}</span>
      </p>
      {/* List of download links/buttons */}
      <div className="space-y-3 mb-6">
        {/* Map over the options array (real or placeholder) */}
        {options.map((option, index) => (
          <a
            key={index}
            href={option.url} // The actual download link for this option
            download // HTML attribute to suggest downloading the linked file
            target="_blank" // Open in a new tab, helps if direct download fails
            rel="noopener noreferrer" // Security measure for target="_blank"
            // Styling for the download button/link
            className="block bg-green-500 hover:bg-green-600 dark:bg-green-600 dark:hover:bg-green-500 text-white font-medium py-3 px-4 rounded-md text-center no-underline transition duration-150 ease-in-out shadow hover:shadow-lg"
          >
            {/* Text describing the download option */}
            Download {option.format} - {option.quality} {option.size ? `(${option.size})` : ''}
          </a>
        ))}
      </div>
      {/* Helpful tip for users */}
      <p className="text-xs text-gray-500 dark:text-gray-400 mb-6 text-center">
         Tip: Right-click the button and choose "Save link as..." if the download doesn't start automatically.
      </p>
      {/* Button to go back and download another video */}
      <button
        onClick={onDownloadAnother} // Call the function passed via props (or placeholder)
        // Styling for the "Download Another" button
        className="w-full bg-blue-600 hover:bg-blue-700 dark:bg-blue-700 dark:hover:bg-blue-600 text-white font-bold py-3 px-4 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-opacity-50 transition-colors duration-300"
      >
        Download Another Video
      </button>
    </div>
  );
};

// Export the component for use in other files
export default DownloadResults;
